<?php
require_once 'config/app.php';require_roles(['admin','operator']);$pageTitle='Pengajuan Peminjaman';
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$pegawai=(int)$_POST['pegawai_id'];$kendaraan=(int)$_POST['kendaraan_id'];$mulai=$_POST['tanggal_pinjam'];$akhir=$_POST['tanggal_kembali_rencana'];
 if(strtotime($akhir)<=strtotime($mulai)){flash('Tanggal kembali harus setelah tanggal pinjam.','danger');redirect('peminjaman.php?action=add');}
 $q=$pdo->prepare("SELECT COUNT(*) FROM peminjaman WHERE kendaraan_id=? AND status IN ('Disetujui','Sedang Digunakan') AND NOT (tanggal_kembali_rencana<=? OR tanggal_pinjam>=?)");$q->execute([$kendaraan,$mulai,$akhir]);if($q->fetchColumn()){flash('Kendaraan sudah memiliki jadwal peminjaman pada rentang tersebut.','danger');redirect('peminjaman.php?action=add');}
 $no=nomor_peminjaman();$q=$pdo->prepare("INSERT INTO peminjaman(nomor_peminjaman,pegawai_id,kendaraan_id,tanggal_pengajuan,tanggal_pinjam,tanggal_kembali_rencana,tujuan,lokasi_tujuan,keperluan,pengemudi,user_id) VALUES(?,?,?,CURDATE(),?,?,?,?,?,?,?)");
 $q->execute([$no,$pegawai,$kendaraan,$mulai,$akhir,trim($_POST['tujuan']),trim($_POST['lokasi_tujuan']),trim($_POST['keperluan']),trim($_POST['pengemudi']),current_user()['id']]);$id=$pdo->lastInsertId();log_status($pdo,$id,'','Menunggu Persetujuan','Pengajuan dibuat');flash('Pengajuan berhasil dibuat dengan nomor '.$no);redirect('peminjaman.php');}
$action=$_GET['action']??'';$pegawai=$pdo->query("SELECT * FROM pegawai ORDER BY nama")->fetchAll();$kendaraan=$pdo->query("SELECT * FROM kendaraan WHERE status='Tersedia' ORDER BY merk")->fetchAll();
$rows=$pdo->query("SELECT p.*,g.nama,k.merk,k.nomor_polisi FROM peminjaman p JOIN pegawai g ON g.id=p.pegawai_id JOIN kendaraan k ON k.id=p.kendaraan_id ORDER BY p.id DESC")->fetchAll();require 'includes/header.php';?>
<div class="d-flex justify-content-between mb-3"><h3>Pengajuan Peminjaman</h3><a class="btn btn-primary" href="?action=add">+ Buat Pengajuan</a></div>
<?php if($action==='add'):?><div class="card mb-4"><div class="card-header bg-white fw-bold">Form Pengajuan Kendaraan</div><div class="card-body"><?php if(!$pegawai||!$kendaraan):?><div class="alert alert-warning">Pastikan data pegawai dan kendaraan berstatus tersedia sudah diinput.</div><?php endif;?><form method="post" class="row g-3"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><div class="col-md-6"><label class="form-label">Pegawai/Peminjam</label><select name="pegawai_id" class="form-select" required><option value="">Pilih pegawai</option><?php foreach($pegawai as $p):?><option value="<?=$p['id']?>"><?=e($p['nama'].' - '.$p['jabatan'])?></option><?php endforeach;?></select></div><div class="col-md-6"><label class="form-label">Kendaraan</label><select name="kendaraan_id" class="form-select" required><option value="">Pilih kendaraan</option><?php foreach($kendaraan as $k):?><option value="<?=$k['id']?>"><?=e($k['merk'].' '.$k['tipe'].' / '.$k['nomor_polisi'])?></option><?php endforeach;?></select></div><div class="col-md-6"><label class="form-label">Tanggal/Jam Pinjam</label><input type="datetime-local" name="tanggal_pinjam" class="form-control" required></div><div class="col-md-6"><label class="form-label">Rencana Kembali</label><input type="datetime-local" name="tanggal_kembali_rencana" class="form-control" required></div><div class="col-md-6"><label class="form-label">Tujuan</label><input name="tujuan" class="form-control" required></div><div class="col-md-6"><label class="form-label">Lokasi Tujuan</label><input name="lokasi_tujuan" class="form-control"></div><div class="col-md-6"><label class="form-label">Pengemudi</label><input name="pengemudi" class="form-control"></div><div class="col-md-6"><label class="form-label">Keperluan</label><input name="keperluan" class="form-control"></div><div class="col-12"><button class="btn btn-primary" <?=$pegawai&&$kendaraan?'':'disabled'?>>Kirim Pengajuan</button> <a class="btn btn-light" href="peminjaman.php">Batal</a></div></form></div></div><?php endif;?>
<div class="card"><div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><th>Nomor</th><th>Peminjam</th><th>Kendaraan</th><th>Jadwal</th><th>Tujuan</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['nomor_peminjaman'])?></td><td><?=e($r['nama'])?></td><td><?=e($r['merk'].' / '.$r['nomor_polisi'])?></td><td><?=e(date('d-m-Y H:i',strtotime($r['tanggal_pinjam'])))?><br><small class="text-muted">s.d. <?=e(date('d-m-Y H:i',strtotime($r['tanggal_kembali_rencana'])))?></small></td><td><?=e($r['tujuan'])?></td><td><?=status_badge($r['status'])?></td><td><a class="btn btn-sm btn-outline-primary" href="surat.php?id=<?=$r['id']?>">Surat</a></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="7" class="text-center p-4">Belum ada pengajuan.</td></tr><?php endif;?></tbody></table></div></div><?php require 'includes/footer.php';?>